//! Golden tests: expected values from the reference tmux 3.8, generated by
//! `tests/keys_cases.sh` into `golden/`. Each file's header in that script
//! says which reference command produced it.

use std::collections::HashMap;

use super::{KeyBindings, display_width};
use crate::cmd::{
    CmdError, CommandCall, ConfigEnv, NoEnv, ParseOpts, parse_argv, parse_config_with,
};
use crate::format::FormatContext;
use crate::keys::Key;

const NAMES: &str = include_str!("golden/names.txt");
const ORDER: &str = include_str!("golden/order.txt");
const FRESH: &str = include_str!("golden/fresh.txt");
const FRESH_N: &str = include_str!("golden/fresh_N.txt");
const OWNER_BINDS: &str = include_str!("golden/owner_binds.conf");
const OWNER_PREFIX: &str = include_str!("golden/owner_prefix.txt");
const OWNER_ROOT: &str = include_str!("golden/owner_root.txt");
const CASES: &str = include_str!("golden/cases.txt");
const CONFIG: &str = include_str!("golden/config.txt");

/// `HOME` in the reference run (`tests/keys_cases.sh` pins it).
const HOME: &str = "/home/vtmux-test";

/// The reference's global environment, as far as the cases read it.
struct Env(HashMap<String, String>);

impl Env {
    fn new() -> Self {
        Self(HashMap::from([("HOME".to_owned(), HOME.to_owned())]))
    }
}

impl ConfigEnv for Env {
    fn var(&self, name: &str) -> Option<String> {
        self.0.get(name).cloned()
    }
    fn home(&self, user: Option<&str>) -> Option<String> {
        match user {
            None => Some(HOME.to_owned()),
            Some(_) => None,
        }
    }
    fn set(&mut self, name: &str, value: &str, _hidden: bool) {
        self.0.insert(name.to_owned(), value.to_owned());
    }
    fn expand(&self, template: &str) -> String {
        crate::format::expand_str(template, &NoVars)
    }
}

struct NoVars;

impl FormatContext for NoVars {
    fn get(&self, _: &str) -> Option<String> {
        None
    }
}

/// A server's key state plus the output of what ran against it.
struct Sim {
    kb: KeyBindings,
    env: Env,
    /// What the reference would have printed (stdout and stderr together).
    out: String,
    /// Commands that are not key commands; the cases never mean to run any.
    other: Vec<&'static str>,
}

impl Sim {
    fn new() -> Self {
        Self {
            kb: KeyBindings::with_defaults(),
            env: Env::new(),
            out: String::new(),
            other: Vec::new(),
        }
    }

    fn say(&mut self, line: &str) {
        self.out.push_str(line);
        self.out.push('\n');
    }

    /// Run commands the way the queue does: a command that fails ends the
    /// rest of its group.
    fn run(&mut self, calls: &[CommandCall]) {
        let mut failed_group = None;
        for call in calls {
            if failed_group == Some(call.group) {
                continue;
            }
            let result = if call.entry.name == "list-keys" {
                let prefix = Key::from_name("C-b").unwrap();
                self.kb
                    .list_keys(&call.args, prefix, &NoVars)
                    .map(|listing| {
                        for line in listing.printed() {
                            self.out.push_str(line);
                            self.out.push('\n');
                        }
                    })
            } else {
                let ran = self.kb.execute(call, &mut self.env);
                // `display-message` run without a client prints nothing in the
                // reference (`bind x display a ; display b` runs the second as
                // its own command); no other command may sneak in.
                if ran.is_none() && call.entry.name != "display-message" {
                    self.other.push(call.entry.name);
                }
                ran.unwrap_or(Ok(()))
            };
            // Every client sits in a key table (`root` for these), which
            // tmux re-creates when a command removes it.
            self.kb.ensure_table("root");
            if let Err(e) = result {
                if let Some(message) = &e.message {
                    self.say(message);
                }
                failed_group = Some(call.group);
            }
        }
    }

    /// One `tmux ARGS...` invocation.
    fn argv(&mut self, words: &[&str]) {
        let words: Vec<String> = words.iter().map(|w| (*w).to_owned()).collect();
        match parse_argv(&words) {
            Ok(calls) => self.run(&calls),
            Err(e) => self.say(&e.to_string()),
        }
    }

    /// `source-file` on `text`: a parse error runs nothing.
    fn source(&mut self, text: &str) {
        match parse_config_with(text, &mut self.env, ParseOpts::default()) {
            Ok(calls) => self.run(&calls),
            Err(e) => self.say(&e.to_string()),
        }
    }

    fn list(&mut self, args: &[&str]) {
        let mut words = vec!["list-keys"];
        words.extend_from_slice(args);
        self.argv(&words);
    }
}

fn blocks(text: &str) -> Vec<(&str, Vec<&str>)> {
    // `### name`, lines, `%%`. Split on '\n' only: some cases hold '\r'.
    let mut out = Vec::new();
    let mut lines = text.split('\n');
    while let Some(line) = lines.next() {
        let Some(name) = line.strip_prefix("### ") else {
            continue;
        };
        let body: Vec<&str> = lines.by_ref().take_while(|l| *l != "%%").collect();
        out.push((name, body));
    }
    out
}

/// `key_string_lookup_string` through `bind-key`, for every row of
/// golden/names.txt: the name tmux prints for the key it parsed, or bind's
/// error.
#[test]
fn key_names_match_reference() {
    let mut failures = Vec::new();
    let mut rows = 0;
    for line in NAMES.lines() {
        let (key, expected) = line.split_once('\t').expect("a tab");
        rows += 1;
        let mut sim = Sim {
            kb: KeyBindings::empty(),
            ..Sim::new()
        };
        sim.argv(&["bind", "-T", "t", "--", key, "display"]);
        let got = if sim.out.is_empty() {
            let mut listing = Sim {
                kb: sim.kb.clone(),
                ..Sim::new()
            };
            listing.list(&["-T", "t", "-F", "#{key_string}"]);
            format!("={}", listing.out.trim_end_matches('\n'))
        } else {
            format!("!{}", sim.out.trim_end_matches('\n'))
        };
        if got != expected {
            failures.push(format!("{key:?}: expected {expected:?}, got {got:?}"));
        }
    }
    assert!(rows >= 300, "{rows} rows");
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// The FACTS in the brief, spelled out so a regenerated golden file cannot
/// quietly change them.
#[test]
fn key_name_facts() {
    let name = |s: &str| Key::from_name(s).map(|k| k.to_string());
    assert_eq!(name("C-i").as_deref(), Some("C-i"));
    assert_eq!(name("Tab").as_deref(), Some("Tab"));
    assert_ne!(Key::from_name("C-i"), Key::from_name("Tab"));
    assert_eq!(name("^[").as_deref(), Some("C-["));
    assert_ne!(Key::from_name("C-A"), Key::from_name("C-a"));
    assert_eq!(name("^A").as_deref(), Some("C-a"));
    assert_eq!(Key::from_name("None"), Some(Key::NONE));
    assert_eq!(Key::from_name("F13"), None);
    let mut sim = Sim::new();
    sim.argv(&["bind", "None", "display"]);
    sim.argv(&["bind", "F13", "display"]);
    assert_eq!(sim.out, "unknown key: None\nunknown key: F13\n");
}

/// Every key string in the default tables round-trips: its name parses back
/// to the same key.
#[test]
fn default_keys_round_trip() {
    let kb = KeyBindings::with_defaults();
    let mut n = 0;
    for (_, table) in kb.tables() {
        for binding in table.bindings() {
            let name = binding.key.to_string();
            // Bindings drop the flag bits `Up` and `F1` carry.
            let parsed = Key::from_name(&name).map(Key::without_flags);
            assert_eq!(parsed, Some(binding.key), "{name}");
            n += 1;
        }
    }
    assert_eq!(n, 308);
}

/// Binding order is numeric key-code order across the whole code space.
#[test]
fn table_order_matches_reference() {
    let want: Vec<&str> = ORDER.lines().collect();
    assert_eq!(want.len(), 82);
    let mut sim = Sim {
        kb: KeyBindings::empty(),
        ..Sim::new()
    };
    // The same keys, in a different binding order, from the script.
    let script = include_str!("../../tests/keys_cases.sh");
    let list = script
        .lines()
        .skip_while(|l| !l.starts_with("ORDER=("))
        .skip(1)
        .take_while(|l| *l != ")")
        .flat_map(shell_words)
        .collect::<Vec<_>>();
    assert_eq!(list.len(), want.len());
    for key in &list {
        sim.argv(&["bind", "-T", "o", "--", key, "display"]);
    }
    sim.list(&["-T", "o", "-F", "#{key_string}"]);
    assert_eq!(sim.out.lines().collect::<Vec<_>>(), want);
}

/// Words of one line of single-quoted shell words (the ORDER array).
fn shell_words(line: &str) -> Vec<String> {
    let mut words = Vec::new();
    let mut rest = line.trim();
    while !rest.is_empty() {
        if let Some(r) = rest.strip_prefix('\'') {
            let end = r.find('\'').expect("closing quote");
            words.push(r[..end].to_owned());
            rest = r[end + 1..].trim_start();
        } else {
            let end = rest.find(' ').unwrap_or(rest.len());
            words.push(rest[..end].to_owned());
            rest = rest[end..].trim_start();
        }
    }
    words
}

fn lines_of(sim: &Sim) -> Vec<&str> {
    sim.out.lines().collect()
}

/// A fresh server's `list-keys`: 308 lines across five tables, byte for byte.
#[test]
fn fresh_list_keys_matches_reference() {
    let mut sim = Sim::new();
    sim.list(&[]);
    let got = lines_of(&sim);
    assert_eq!(got.len(), 308);
    let want: Vec<&str> = FRESH.lines().collect();
    assert_eq!(want.len(), 308);
    for (i, (g, w)) in got.iter().zip(&want).enumerate() {
        assert_eq!(g, w, "line {}", i + 1);
    }
}

/// The five tables and their sizes (cmd-list-keys.c over key-bindings.c).
#[test]
fn fresh_tables() {
    let kb = KeyBindings::with_defaults();
    let sizes: Vec<(&str, usize)> = kb
        .tables()
        .map(|(n, t)| (n, t.bindings().count()))
        .collect();
    assert_eq!(
        sizes,
        [
            ("copy-mode", 78),
            ("copy-mode-vi", 88),
            ("move", 19),
            ("prefix", 93),
            ("root", 30)
        ]
    );
}

#[test]
fn fresh_notes_match_reference() {
    let mut sim = Sim::new();
    sim.list(&["-N"]);
    assert_eq!(sim.out, FRESH_N);
}

/// After the owner's `bind`/`unbind` lines, `-T prefix` and `-T root`.
#[test]
fn owner_binds_match_reference() {
    let mut sim = Sim::new();
    sim.source(OWNER_BINDS);
    assert!(
        !sim.out.contains("unknown") && !sim.out.contains("error"),
        "{}",
        sim.out
    );
    sim.out.clear();
    sim.list(&["-T", "prefix"]);
    assert_eq!(sim.out, OWNER_PREFIX);
    sim.out.clear();
    sim.list(&["-T", "root"]);
    assert_eq!(sim.out, OWNER_ROOT);
}

/// Sequences of key commands, each with the reference's combined output.
#[test]
fn command_sequences_match_reference() {
    let mut failures = Vec::new();
    let cases = blocks(CASES);
    assert!(cases.len() >= 90, "{} cases", cases.len());
    for (name, body) in cases {
        let split = body
            .iter()
            .position(|l| !l.starts_with("$ "))
            .unwrap_or(body.len());
        // The expected output may itself hold lines starting with "$ "
        // (a `bind $` listing), so only the leading run is commands: the
        // script prints exactly one `$ ` line per command.
        let (commands, expected) = body.split_at(split);
        let mut sim = Sim::new();
        for command in commands {
            let words: Vec<&str> = command[2..].split('\x1f').collect();
            sim.argv(&words);
        }
        assert!(sim.other.is_empty(), "{name}: ran {:?}", sim.other);
        let got: Vec<&str> = sim.out.lines().collect();
        if got != expected {
            failures.push(format!(
                "### {name}\nexpected:\n{}\ngot:\n{}",
                expected.join("\n"),
                got.join("\n")
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n\n"));
}

/// Config text: `{ }` blocks, canonical printing, errors.
#[test]
fn config_cases_match_reference() {
    let mut failures = Vec::new();
    let cases = blocks(CONFIG);
    assert!(cases.len() >= 170, "{} cases", cases.len());
    for (name, body) in cases {
        let at = body.iter().position(|l| *l == "---").expect("a ---");
        let mut text = body[..at].join("\n");
        text.push('\n');
        let expected = &body[at + 1..];
        let mut sim = Sim {
            kb: KeyBindings::empty(),
            ..Sim::new()
        };
        sim.source(&text);
        assert!(sim.other.is_empty(), "{name}: ran {:?}", sim.other);
        let mut got: Vec<String> = sim.out.lines().map(|l| format!("! {l}")).collect();
        let errors = got.len();
        let mut listing = Sim {
            kb: sim.kb.clone(),
            ..Sim::new()
        };
        listing.list(&["-T", "t", "-F", "#{key_string}|#{key_command}"]);
        got.extend(listing.out.lines().map(str::to_owned));
        // The reference prints a missing table's error where the list goes.
        if got != expected {
            failures.push(format!(
                "### {name} ({errors} errors)\n{text}expected:\n{}\ngot:\n{}",
                expected.join("\n"),
                got.join("\n")
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n\n"));
}

#[test]
fn display_width_counts_columns() {
    assert_eq!(display_width("abc"), 3);
    assert_eq!(display_width("日本"), 4);
    assert_eq!(display_width("é"), 1);
    assert_eq!(display_width("\u{7f}"), 0);
    assert_eq!(display_width("a\u{1}b"), 2);
}

#[test]
fn default_bind_strings_parse_without_env() {
    // The defaults are parsed with no environment at all.
    let mut env = NoEnv;
    let list = crate::cmd::parse_string("bind -N x a { display b }", &mut env).unwrap();
    assert_eq!(list.calls.len(), 1);
    let err: CmdError = crate::cmd::parse_string("bind a {", &mut env).unwrap_err();
    assert_eq!(err.to_string(), "syntax error");
}
